const form=document.getElementById("requirement-builder");const params=new URLSearchParams(location.search);["city","deal","size"].forEach(k=>{const el=form.elements.namedItem(k);if(params.has(k)&&Array.from(el.options).some(o=>o.value===params.get(k)))el.value=params.get(k)});form.addEventListener("submit",event=>{event.preventDefault();const values=new FormData(form);const lines=["RGJ COMMERCIAL — INDUSTRIAL PROPERTY REQUIREMENT","Prepared: "+new Date().toLocaleDateString("en-CA"),...Array.from(values,([k,v])=>k.toUpperCase()+": "+v),"","Prepared locally. This brief has not been submitted."];const url=URL.createObjectURL(new Blob([lines.join("\n")],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="RGJ_Industrial_Requirement.txt";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById("brief-status").textContent="Your download is ready. No inquiry has been sent."});